#include <iostream>
#include <type_traits>

template <typename T>
typename std::enable_if<std::is_integral<T>::value, void>::type
print(T val) {
    std::cout << "Integral: " << val << std::endl;
}

template <typename T>
typename std::enable_if<!std::is_integral<T>::value, void>::type
print(T val) {
    std::cout << "Non-integral: " << val << std::endl;
}

// Example usage:
// print(5);       // Calls integral version
// print(3.14);    // Calls non-integral version
